"""Reproduce saved predictions and test shuffled-audio control, without retraining."""
from pathlib import Path
import sys,json,numpy as np,joblib
from scipy.stats import binomtest
from train_audio import baseline,combine,probs
from train import metrics,SEED
ROOT=Path(__file__).resolve().parent
z=np.load(ROOT/'features.npz');motion=np.load(ROOT.parent/'normalization-audit/features.npz');idx=z['idx'];mask=(idx>=520)&(z['w']==1);valid=z['valid'];y=z['y'];evaluation=joblib.load(ROOT/'evaluation-model.joblib');final=joblib.load(ROOT/'model.joblib');report=json.loads((ROOT/'metrics.json').read_text())
# Check scalers and saved-model parity; selected config is not augmented in this run.
assert evaluation['config']['augment'] is False
for bundle,fitmask in [(evaluation,idx<520),(final,np.ones(len(idx),bool))]:
 A=z['audio'][fitmask&valid]
 for model in bundle['audio']:
  scaler=model.named_steps['standardscaler'];assert scaler.n_samples_seen_==len(A);np.testing.assert_allclose(scaler.mean_,A.mean(0),atol=1e-9);T=scaler.transform(A);assert np.isfinite(T).all();assert np.max(np.abs(T.mean(0)))<1e-7
bp=baseline(evaluation['baseline'],motion['motion'][mask],motion['light'][mask]);ap=probs(evaluation['audio'],z['audio'][mask]);p=np.column_stack([x.argmax(1) for x in combine(bp,ap,evaluation['alpha'],evaluation['gate'],z['quality'][mask],valid[mask])]);truth=y[mask]
held=json.loads((ROOT/'heldout-predictions.json').read_text());expected=np.array([r['prediction'] for r in held]);assert np.array_equal(p,expected)
base=np.column_stack([a.argmax(1) for a in bp]);oldhit=(base==truth).all(1);newhit=(p==truth).all(1);wins=int((~oldhit&newhit).sum());losses=int((oldhit&~newhit).sum());changed=int((base!=p).any(1).sum());paired_p=float(binomtest(wins,wins+losses,p=.5).pvalue) if wins+losses else 1.
rng=np.random.default_rng(SEED);scores=[]
for _ in range(1000):
 perm=rng.permutation(mask.sum());q=combine(bp,[a[perm] for a in ap],evaluation['alpha'],evaluation['gate'],z['quality'][mask][perm],valid[mask][perm]);pr=np.column_stack([a.argmax(1) for a in q]);scores.append(float((pr==truth).all(1).mean()))
actual=float(newhit.mean());perm_p=float((1+sum(s>=actual-1e-12 for s in scores))/(len(scores)+1));report['paired_comparison']=dict(changed_predictions=changed,fixed_exact=wins,lost_exact=losses,mcnemar_exact_two_sided_p=paired_p)
report['shuffled_audio_1000']=dict(mean_exact=float(np.mean(scores)),p95_exact=float(np.percentile(scores,95)),fraction_at_least_actual=perm_p,n=1000,note='Same audio features permuted across held-out examples; empirical negative control, not fresh-data validation.')
report['verification']='Saved evaluation model reproduces all 217 predictions; audio scalers fit the correct training subset, mean~0, no nonfinite values; final and evaluated models separate.'
(ROOT/'metrics.json').write_text(json.dumps(report,ensure_ascii=False,indent=2))
lines=['Добавление микрофона с учётом фонового звука','', 'Источник: уже записанный встроенный микрофон, 44100 Гц, Float32; новая запись не включалась.','Аудио привязано к часам датчиков по audio-chunks.jsonl, паузы не считаются непрерывным звуком.','Тап ищется только в коротком окне возле импульса IMU, а не по всей дорожке.','Шумовой спектр оценивается до тапа (−340..−100 мс). Извлекается 202 признака спектра, атаки, затухания, относительного превышения фона и формы импульса.','Абсолютные признаки речи/музыки и распознавание речи не используются.','Стандартная нормализация обучается только на обучающей части.','', 'Проверенные варианты: линейный классификатор, SVM, ExtraTrees, LightGBM; SVM с добавлением реальных фоновых отрезков в обучение.','Фон для смешивания берётся только из обучающего прохода, не из валидации или теста.','Также сравнивались фиксированный вес звука и вес, уменьшающийся при низком отношении сигнал/шум.','Выбран на втором проходе линейный классификатор аудио с фиксированным весом 10%; остальные 90% — прежняя модель движения/угла/света.','Усиление шума и автоматическое уменьшение веса проверены, но выбранный вариант на валидации оказался лучше без них.','', 'Повторная проверка на тех же 217 автоматических тапах третьего прохода:']
for title,key in [('Без микрофона','previous_same_test'),('С микрофоном','test'),('Только звук (отдельная выбранная аудиомодель)','audio_only_test')]:
 r=report[key];lines.append(f"{title}: точная клетка {100*r['exact']:.2f}% ({round(r['exact']*r['n'])}/{r['n']}), рядом ≤1 клетка по каждой оси {100*r['within_one']:.2f}%, средний промах {r['mean_distance_cells']:.2f} клетки.")
lines += ['',f'Изменено предсказаний: {changed}; исправлено точных ошибок: {wins}; потеряно точных попаданий: {losses}.',f'Точная парная проверка улучшения: p={paired_p:.3f}.',f"1000 перемешиваний звука: средняя точность {100*np.mean(scores):.2f}%, не хуже настоящего звука — {100*perm_p:.1f}% перемешиваний.",'Это небольшой результат; статистически убедительного выигрыша пока не получено. Нужен отдельный новый сеанс для подтверждения.','',f"Медиана отношения сигнал/фон: {report['quality_summary']['median_snr_db']:.2f} дБ; медианное смещение найденного аудиоимпульса относительно IMU: {report['quality_summary']['median_audio_alignment_ms']:.1f} мс.",f"Аудиопокрытие: {report['quality_summary']['valid_test']}/217 тестовых тапов. Сложные случаи не удалялись из итогового теста.",'', 'model.joblib — отдельный финальный вариант с микрофоном, обученный после оценки на всех пригодных данных.','evaluation-model.joblib — вариант первых двух проходов, к которому относятся проценты выше.','Приложение не менялось: пока использует прежнюю модель без микрофона.','Третий проход уже использовался ранее; это повторное сравнение, не независимая проверка.','Источники и воспроизведение: audio_features.py, train_audio.py, verify_report.py.']
(ROOT/'RESULTS.txt').write_text('\n'.join(lines)+'\n');print(json.dumps(dict(changes=report['paired_comparison'],permutation=report['shuffled_audio_1000'],verification='passed'),indent=2))
